            color = grid[r][c]
            if color and all(grid[rr][cc] == 3 for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                centers.append((r, c, color))
    # Extend each colored plus across its row and column. Vertical strokes are
    # applied last, so they determine colors where projections intersect.
    for r, c, color in centers:
        for x in range(w):
            if grid[r][x] != 3:
                out[r][x] = color
    for r, c, color in centers:
        for y in range(h):
            if grid[y][c] != 3:
                out[y][c] = color
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 3
    return out

