 "content": "def transform(grid):
    """Project colored pluses along rows and columns; gray pluses mask tracks."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(grid[y][x] == 3 for y, x in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))):
                centers.append((r, c, grid[r][c]))

    # Colored horizontal rays cross their own adjacent arm, then stop at the
    # next gray marker. Horizontal strokes are drawn before vertical strokes.
    for r, c, color in centers:
        if color == 0:
            continue
        for dc in (-1, 1):
            x = c + dc
            own_arm = True
            while 0 <= x < w:
                if grid[r][x] == 3:
                    if own_arm:
                        own_arm = False
                        x += dc
                        continue
                    break
                out[r][x] = color
                own_arm = False
                x += dc

    # A marker-only plus contributes a blank horizontal track.
    for r, c, color in centers:
        if color == 0:
            for x in range(w):
                if grid[r][x] != 3:
                    out[r][x] = 0

    # Vertical projections overlay horizontal ones. Blank vertical tracks are
    # applied after colored tracks and therefore mask their intersections.
    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            own_arm = True
            while 0 <= y < h:
                if grid[y][c] == 3:
                    if own_arm:
                        own_arm = False
                        y += dr
                        continue
                    break
                if grid[y][c] != 0:
                    break
                out[y][c] = color
                own_arm = False
                y += dr

    for r, c, color in centers:
        if color == 0:
            for y in range(h):
                if grid[y][c] != 3:
                    out[y][c] = 0

    # Gray markers are structural and always remain unchanged.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 3
    return out


